// F69: testar scripts/prova-ordning.cjs i ett eget litet git-repo under os.tmpdir().
// Rör inte repots egna grenar och tar bort sitt repo efteråt. Kräver git.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const skript = path.resolve('scripts', 'prova-ordning.cjs');
const krav = {};
krav.skriptetFinns = fs.existsSync(skript);
const kod = krav.skriptetFinns ? fs.readFileSync(skript, 'utf8') : '';
const utanKommentarer = kod.split('\n').filter((r) => !r.trim().startsWith('//')).join('\n');
const kravda = [...utanKommentarer.matchAll(/require\('([^']+)'\)/g)].map((m) => m[1]);
krav.ingaBeroenden = kravda.length > 0 && kravda.every((m) => ['fs', 'os', 'path', 'child_process'].includes(m));
krav.ingenPushEllerNat = !/'(push|fetch|pull|clone|remote|branch|reset|checkout|switch)'/.test(utanKommentarer) && !/https?:/.test(utanKommentarer);
krav.aiMarkt = kod.includes('AI-skapat') && kod.includes('Generated by AI, Directed by MS');

const repo = fs.mkdtempSync(path.join(os.tmpdir(), 'prova-ordning-test-'));
const g = (...a) => spawnSync('git', ['-c', 'user.name=test', '-c', 'user.email=test@example.invalid', ...a], { cwd: repo, encoding: 'utf8' });
const skriv = (f, t) => { fs.mkdirSync(path.dirname(path.join(repo, f)), { recursive: true }); fs.writeFileSync(path.join(repo, f), t); };
const kor = (...a) => { const r = spawnSync(process.execPath, [skript, ...a], { cwd: repo, encoding: 'utf8' }); let j = null; try { j = JSON.parse(r.stdout.trim().split('\n').pop()); } catch (e) {} return { kod: r.status, j }; };
try {
  g('init', '-q', '-b', 'main');
  skriv('nytt.txt', 'gammal\n');
  skriv('tests/kor-alla.cjs', "const fs=require('fs');const r=fs.existsSync('rod.txt');console.log(r?'Röda: 1':'Alla gröna: 1 av 1.');process.exit(r?1:0);\n");
  g('add', '.'); g('commit', '-q', '-m', 'bas');
  const gren = (namn, f, t) => { g('switch', '-q', '-c', namn, 'main'); skriv(f, t); g('add', '.'); g('commit', '-q', '-m', namn); g('switch', '-q', 'main'); };
  gren('a', 'nytt.txt', 'a\ngammal\n');
  gren('b', 'nytt.txt', 'b\ngammal\n');
  gren('c', 'c.txt', 'c\n');
  gren('d', 'rod.txt', 'x\n');
  const fore = g('for-each-ref', '--format=%(refname) %(objectname)').stdout + g('rev-parse', 'HEAD').stdout;

  if (krav.skriptetFinns) {
    const ren = kor('a', 'c');
    krav.renOrdning = ren.kod === 0 && ren.j && ren.j.ok === true && ren.j.steg.every((s) => s.ok === true) && ren.j.tester && ren.j.tester.ok === true;
    const k = kor('a', 'b', 'c');
    krav.konfliktHittas = k.kod === 1 && k.j && k.j.ok === false && k.j.steg[0].ok === true && k.j.steg[1].ok === false &&
      JSON.stringify(k.j.steg[1].konflikter) === '["nytt.txt"]' && k.j.tester === null;
    krav.stannarVidKonflikt = !!(k.j && k.j.steg[2] && k.j.steg[2].ok === null && k.j.steg[2].anm === 'inte provad');
    const r = kor('--bas', 'main', 'c', 'd');
    krav.rodaTesterSyns = r.kod === 1 && r.j && r.j.steg.every((s) => s.ok === true) && r.j.tester && r.j.tester.ok === false;
    krav.felAnrop = kor().kod === 2 && kor('--bas').kod === 2;
  }
  const efter = g('for-each-ref', '--format=%(refname) %(objectname)').stdout + g('rev-parse', 'HEAD').stdout;
  krav.ingetKvar = fore === efter && g('worktree', 'list').stdout.trim().split('\n').length === 1 && g('status', '--porcelain').stdout.trim() === '';
} finally {
  fs.rmSync(repo, { recursive: true, force: true });
}

for (const k of ['renOrdning', 'konfliktHittas', 'stannarVidKonflikt', 'rodaTesterSyns', 'felAnrop']) if (!(k in krav)) krav[k] = false;
const ok = Object.values(krav).every(Boolean);
if (!ok) console.error('Röda: ' + Object.keys(krav).filter((k) => !krav[k]).join(', '));
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
